CREATE DATABASE IF NOT EXISTS sever_stroy CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sever_stroy;
CREATE TABLE IF NOT EXISTS leads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(190) NULL, message TEXT NULL,status VARCHAR(24) NOT NULL DEFAULT 'new',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_created_at(created_at));
